upper_before=json.dumps(data['boxes']['upper-middle'],separators=(',',':'))
box=data['boxes']['lower-middle']
assert {r['id'] for r in box['records']}==set(BASE_POLYGONS)
for row in box['records']:
 id=row['id'];base=BASE_POLYGONS[id];old=row['polygon']
 assert old[2]==base[2] and old[5]==base[5],(id,'reviewed body points changed')
 tl,tr,br,bl=END_Y[id]
 poly=[on_side(base,0,5,tl),on_side(base,1,2,tr),old[2],on_side(base,3,2,br),on_side(base,4,5,bl),old[5]]
 for label,p in OVERRIDES.get(id,{}).items():poly[{'TL':0,'TR':1,'BR':3,'BL':4}[label]]=p
 row['polygon']=poly
 row['anchor']=[round((poly[3][0]+poly[4][0])/2,1),round((poly[3][1]+poly[4][1])/2,1)]
 row['endpointNotes']='Per-sleeve front-face cap and foot heights measured in the EXIF-oriented original;2–4px inset where the paper edge is clear. Reviewed side/body anchors are preserved; tiny rounded and ragged tips use straight corner approximations.'
 if id=='lower-middle-01':row['endpointNotes']='The rounded paper heel is visible near y2970; measured front-face corners end at y2965/2966 with a conservative inset. The nearby outer frame corner is photo-clipped, but the record heel is visible. Existing body points are preserved.'
box['notes']='Single physical compartment. Per-sleeve cap/foot corner heights measured from full-resolution EXIF-oriented original photos. Existing source middle-body vertices and stable IDs are preserved. Marker anchors are the individual foot midpoints. Worn or rounded paper corners use a conservative straight edge, generally2–4px inside visible sleeve faces; shelf shadows and exposed white frame are excluded. The outer frame corner is photo-clipped, but the first paper heel is visible and measured near y2970; its mask stops on the sleeve rather than the gray shelf shadow below it.'
assert json.dumps(data['boxes']['upper-middle'],separators=(',',':'))==upper_before
for row in box['records']:
 q=row['polygon'];assert all(0<=x<=4032 and 0<=y<=3024 for x,y in q),row['id']
